    ("LUT conversion", "{\"color\":{\"lut\":7}}"),
]
for (name, json) in cases {
    let row = try JSONDecoder().decode(Row.self, from: Data(json.utf8))
    let shipped = row.color != nil
    let converts = row.color?.log != nil || row.color?.lut != nil
    print("\(name): warning=\(shipped) cameraLogConverts=\(converts)")
}

